<?php
namespace EyeDonation\Search;
defined('ABSPATH') || exit;
add_action('admin_menu',function(){add_menu_page('Search','Search','manage_options','eyedonation-search',__NAMESPACE__.'\\admin_screen','dashicons-search',80);});
function admin_screen(){if(!current_user_can('manage_options'))return;$message='';
 if($_SERVER['REQUEST_METHOD']==='POST'){check_admin_referer('eds_settings');if(isset($_POST['rebuild'])){request_rebuild();$message='Rebuild queued; public-text batches run through WordPress cron.';}else{$value=settings();foreach(['enhanced','filters','highlight'] as $key)$value[$key]=!empty($_POST[$key]);$value['per_page']=(int)($_POST['per_page']??6);$value['excluded_types']=array_values(array_filter(array_map('sanitize_key',preg_split('/[\s,]+/',wp_unslash($_POST['excluded_types']??'')))));$raw=trim(wp_unslash($_POST['excluded_ids']??''));$ids=$raw?preg_split('/[\s,]+/',$raw):[];$valid=true;foreach($ids as $id)if(!ctype_digit($id)||!$id)$valid=false;$value['excluded_ids']=array_map('intval',$ids);$value['groups']=json_decode(wp_unslash($_POST['groups']??'{}'),true);$result=$valid?update_settings($value):new \WP_Error('ids','Excluded IDs must be positive integers.');$message=is_wp_error($result)?$result->get_error_message():'Settings saved.';}}
 $s=settings();echo '<div class="wrap"><h1>Search</h1><p role="status">'.esc_html($message).'</p><form method="post">';wp_nonce_field('eds_settings');foreach(['enhanced'=>'Enhanced search','filters'=>'Group filters','highlight'=>'Highlight matching terms'] as $key=>$label)echo '<p><label><input type="checkbox" name="'.esc_attr($key).'" value="1" '.checked($s[$key],true,false).'> '.esc_html($label).'</label></p>';
 echo '<p><label>Results per page <input type="number" min="1" max="50" name="per_page" value="'.esc_attr($s['per_page']).'"></label></p><p><label>Excluded post types (slugs separated by commas)<br><input class="regular-text" name="excluded_types" value="'.esc_attr(implode(', ',$s['excluded_types'])).'"></label></p><p><label>Excluded post IDs (separated by commas)<br><input class="regular-text" name="excluded_ids" value="'.esc_attr(implode(', ',$s['excluded_ids'])).'"></label></p><p>Group mappings use JSON: each slug accepts label, enabled (true/false), types (post-type slugs), terms (taxonomy → term IDs), and ancestors (page IDs). Object order controls display order. Specific taxonomy/ancestor matches take precedence over general type mappings. Missing mappings are rejected.</p><label for="eds-groups">Ordered group mappings</label><br><textarea id="eds-groups" name="groups" rows="18" cols="90">'.esc_textarea(wp_json_encode($s['groups'],JSON_PRETTY_PRINT)).'</textarea>';submit_button('Save settings');echo '<button name="rebuild" value="1" class="button">Rebuild public search text</button></form><p>Rebuild status: '.esc_html(get_option('eds_rebuild_job')?'Pending/running':'Idle').'</p></div>';
}
